insomnia.test('Returns HTTP 200', () => {
  insomnia.expect(insomnia.response.status).to.eql(200);
});
insomnia.test('Returns exactly three valid recipes', () => {
  const body = insomnia.response.json();
  insomnia.expect(body.recipes).to.be.an('array').with.lengthOf(3);
  for (const recipe of body.recipes) {
    insomnia.expect(recipe.title).to.be.a('string');
    insomnia.expect(recipe.title.trim().length).to.be.above(0);
    insomnia.expect(recipe.ingredients).to.be.an('array').that.is.not.empty;
    for (const ingredient of recipe.ingredients) {
      insomnia.expect(ingredient.name).to.be.a('string');
      insomnia.expect(ingredient.name.trim().length).to.be.above(0);
      insomnia.expect(ingredient.missing).to.be.a('boolean');
    }
    insomnia.expect(recipe.instructions).to.be.an('array').that.is.not.empty;
    for (const step of recipe.instructions) {
      insomnia.expect(step).to.be.a('string');
      insomnia.expect(step.trim().length).to.be.above(0);
    }
    insomnia.expect(Number.isInteger(recipe.estimatedCookTime)).to.eql(true);
    insomnia.expect(recipe.estimatedCookTime).to.be.above(0);
    if (recipe.servings !== undefined) {
      insomnia.expect(Number.isInteger(recipe.servings)).to.eql(true);
      insomnia.expect(recipe.servings).to.be.above(0);
    }
  }
});

